
const TZ='Africa/Johannesburg',KEY='ares_v1';
const Q=[
["n1","CompTIA Network+","Subnetting","How many usable host addresses are in a /26 network?",["62","64","30","126"],[0],"A /26 leaves 6 host bits: 2^6 = 64 addresses, minus network and broadcast = 62. 30 is a /27, 126 is a /25."],
["n2","CCNA","Ports","Which protocol and port does DNS use for standard queries?",["UDP 53","TCP 25","UDP 67","TCP 443"],[0],"Standard DNS queries use UDP 53 (TCP 53 for large responses and zone transfers). 67 is DHCP, 25 is SMTP, 443 is HTTPS."],
["n3","CCNA","Layers","At which OSI layer does a switch normally forward frames?",["Layer 2","Layer 3","Layer 4","Layer 1"],[0],"Switches use MAC addresses at Layer 2. Routers work at Layer 3 using IP addresses."],
["c1","Security+","CIA triad","A hash is stored alongside a downloaded file so tampering can be spotted. Which property does this support?",["Integrity","Confidentiality","Availability","Non-repudiation"],[0],"Hash comparison detects modification, which is integrity. Confidentiality would need encryption."],
["c2","Security+","IAM","Which TWO measures best reduce the risk of stolen passwords being used?",["Multi-factor authentication","Longer password rotation notices only","Conditional access policies","Shared admin accounts"],[0,2],"MFA and conditional access add checks beyond the password. Shared admin accounts weaken accountability."],
["c3","CySA+","Phishing","An email has a mismatched Reply-To domain and urgent payment wording. What is the best FIRST analyst action?",["Inspect headers and sender domain in an isolated workflow","Reply to ask if it is genuine","Forward to the whole company","Delete it and close the case"],[0],"Header and domain analysis gathers evidence safely. Replying contacts the attacker, and deleting loses evidence."],
["a1","AZ-104","Azure RBAC","Which Azure feature assigns permissions at subscription, resource group or resource scope?",["Role-based access control","Azure Policy","Resource locks","Tags"],[0],"RBAC grants who can do what at a scope. Policy governs resource configuration, locks prevent changes, tags only label."],
["a2","AZ-104","Networking","Which resource filters inbound and outbound traffic to a subnet or NIC by port and IP?",["Network security group","Azure DNS","Load balancer","Route table"],[0],"An NSG holds allow/deny rules. A route table steers traffic but does not filter it."],
["s1","SC-200","KQL","Which KQL operator filters rows in a table?",["where","project","summarize","extend"],[0],"where filters rows. project selects columns, extend adds columns, summarize aggregates."],
["s2","SC-200","Sentinel","In Microsoft Sentinel, what do analytics rules primarily do?",["Detect threats in logs and raise alerts or incidents","Store raw logs cheaply","Manage user licences","Deploy virtual machines"],[0],"Analytics rules run queries on ingested data and create alerts or incidents."],
["i1","Cloud security","Shared responsibility","In IaaS, who is responsible for patching the guest operating system?",["The customer","The cloud provider","Both equally by default","Nobody"],[0],"With IaaS the provider secures the underlying platform, while the customer manages the guest OS and above."],
["s5-01","SC-500","Identity: Conditional Access","You want users with risky sign-ins to be forced through MFA automatically. What should you configure?",["A resource lock on the subscription","A Conditional Access policy that uses the sign-in risk condition","A network security group rule","An Azure Policy initiative"],[1],"Conditional Access can use Entra ID Protection risk signals to require MFA. Locks, NSGs and Azure Policy do not evaluate sign-in risk."],
["s5-02","SC-500","Identity: PIM","Administrators should hold a privileged role only when needed, for a limited time and with approval. Which feature fits?",["Privileged Identity Management with eligible assignments","Permanent Owner assignments","Security defaults","Self-service password reset"],[0],"PIM provides just-in-time, time-bound, approval-based activation of eligible roles. Permanent assignments are the opposite of least privilege."],
["s5-03","SC-500","Identity: Managed identities","An Azure Function must read secrets from Key Vault without any stored credentials. What is the best approach?",["Store a service principal secret in app settings","Embed the vault key in the code","Use a shared admin account","Enable a managed identity and grant it a Key Vault secrets role"],[3],"A managed identity gives the app an identity that Azure manages, so no secret is stored. Stored secrets and shared accounts can leak."],
["s5-04","SC-500","Governance: Azure Policy","You must prevent anyone, whatever their role, from creating storage accounts that allow public blob access. What should you use?",["RBAC Reader role","Azure Policy with a deny effect","Network security groups","Resource tags"],[1],"Azure Policy enforces resource configuration at creation time. RBAC controls who can act, not what configuration is allowed."],
["s5-05","SC-500","Networking: Private endpoints","A storage account must be reachable only through a private IP address inside your virtual network. What should you deploy?",["A service endpoint only","A public IP on the storage account","A private endpoint with private DNS","An NSG on the storage account"],[2],"A private endpoint gives the service a private IP in your VNet. Service endpoints still use the service's public endpoint, and NSGs do not attach to storage accounts."],
["s5-06","SC-500","Networking: WAF","Which control best protects a public web application from SQL injection and cross-site scripting?",["A network security group","A route table","Azure Web Application Firewall","A VNet peering"],[2],"A WAF inspects HTTP traffic for application-layer attacks. An NSG filters by IP and port only and cannot inspect request content."],
["s5-07","SC-500","Storage: Encryption keys","Your policy requires you to control and rotate the keys that encrypt storage data at rest. What do you use?",["Customer-managed keys in Key Vault","Disabling encryption","Shared access signatures","Anonymous access"],[0],"Storage is encrypted by default with Microsoft-managed keys. Customer-managed keys in Key Vault give you control over the key and its rotation. SAS tokens control access, not encryption."],
["s5-08","SC-500","Databases: Always Encrypted","Database administrators must not be able to read plaintext social security numbers in Azure SQL. Which feature fits best?",["Transparent data encryption","Dynamic data masking only","Always Encrypted","A firewall rule"],[2],"Always Encrypted keeps the keys with the client, so the server and admins only see ciphertext. TDE protects files at rest, and masking only obscures results."],
["s5-09","SC-500","Networking: Azure Firewall","You want central filtering of outbound traffic from several spoke networks, including FQDN rules. What fits best?",["NSGs on every NIC only","Azure Firewall in a hub network with user-defined routes","Public IPs on each VM","A storage firewall"],[1],"Azure Firewall in a hub, with UDRs sending spoke traffic through it, centralises FQDN and network filtering. Per-NIC NSGs cannot filter by FQDN."],
["s5-10","SC-500","Compute: Defender for Containers","You need vulnerability scanning of container images stored in a registry. Which service should you enable?",["Azure DNS","Defender for Containers in Defender for Cloud","Azure Backup","Traffic Manager"],[1],"Defender for Containers includes registry image vulnerability assessment. The other services do not scan images."],
["s5-11","SC-500","Compute: Just-in-time access","You want to reduce exposure of RDP and SSH ports on virtual machines. What helps most?",["Leaving ports open to the internet","Just-in-time VM access in Defender for Cloud","Disabling logging","Using shared local admin passwords"],[1],"JIT access keeps management ports closed and opens them briefly for approved requests, shrinking the attack surface."],
["s5-12","SC-500","AI security: Prompt injection","An AI agent reads a web page containing hidden instructions to send out internal data. Which response best reduces this risk?",["Give the agent an Owner role so it can recover","Raise the model temperature","Disable TLS on the agent's connections","Apply least privilege to the agent's identity and tools, and treat retrieved content as untrusted with input filtering"],[3],"Prompt injection hides instructions in content the agent processes. Limiting what the agent can do and filtering untrusted input contains the damage. Broad roles make it worse."],
["s5-13","SC-500","AI security: Data oversharing","An AI assistant shows a user a confidential file because the SharePoint site was overshared. What is the best fix?",["Correct the site permissions and apply sensitivity labels","Turn off Conditional Access","Give more users access","Rename the file"],[0],"AI assistants generally respect existing permissions, so the root cause is oversharing. Fix access and label sensitive data (Microsoft Purview) rather than blaming the assistant."],
["s5-14","SC-500","Posture: Multicloud","You want to see the security posture of AWS accounts alongside Azure subscriptions in one place. What should you do?",["Create a VNet peering to AWS","Use Azure Backup","Connect the AWS accounts to Defender for Cloud","Install an NSG in AWS"],[2],"Defender for Cloud supports multicloud connectors so AWS resources appear in the same posture view. Networking and backup do not provide posture visibility."],
["s5-15","SC-500","Monitoring: Sentinel analytics","You want an alert when many failed sign-ins from one IP address are followed by a success. What should you create in Microsoft Sentinel?",["A workbook only","A resource lock","A DNS zone","A scheduled analytics rule using a KQL query"],[3],"A scheduled analytics rule runs a KQL query over ingested sign-in logs and creates alerts or incidents. Workbooks only visualise data."]
];
let S;const def={v:1,name:'Jeff',target:'2027-01-31',tasks:[],checkins:{},study:[],attempts:[],why:{a:'',e:'',c:''},
certs:[["AZ-900","Earned (unverified)",""],["SC-900","Earned (unverified)",""],["Security+","Earned (unverified)",""],["CySA+","Earned (unverified)",""],["SC-200","Earned (unverified)",""],["AZ-104","Planned","2026-10-20"],["SC-500","Planned","2026-10-21"],["AI-901","Planned (provisional: late Nov to mid Dec 2026)",""]].map(x=>({id:x[0],status:x[1],date:x[2]}))};
try{S=JSON.parse(localStorage.getItem(KEY))||null}catch(e){S=null}
if(!S||S.v!==1)S=JSON.parse(JSON.stringify(def));
let mem=false;function save(){try{localStorage.setItem(KEY,JSON.stringify(S))}catch(e){mem=true}}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tk=(d=new Date())=>d.toLocaleDateString('en-CA',{timeZone:TZ});
const ms=d=>Date.parse(d+'T00:00:00+02:00')-Date.now();
const $=id=>document.getElementById(id);
let view='home',quiz=null;
const tabs=[['home','Home'],['week','Week'],['vigil','VIGIL'],['practice','Practice'],['certs','Certs'],['roadmap','Roadmap'],['settings','Settings']];
function nav(){$('nav').innerHTML='<div class="logo">ARES</div>'+tabs.map(t=>`<button class="${view==t[0]?'on':''}" onclick="go('${t[0]}')">${t[1]}</button>`).join('')}
function go(v){view=v;render()}
function greet(){const h=+new Date().toLocaleString('en-GB',{timeZone:TZ,hour:'numeric',hour12:false});return h<12?'Good morning':h<18?'Good afternoon':'Good evening'}
function streak(){let n=0,d=new Date();if(!S.checkins[tk(d)])d.setDate(d.getDate()-1);while(S.checkins[tk(d)]){n++;d.setDate(d.getDate()-1)}return n}
function hours(days){const c=Date.now()-days*864e5;return S.study.filter(s=>Date.parse(s.date)>=c).reduce((a,s)=>a+s.min,0)/60}
function weak(){const m={};S.attempts.forEach(a=>{(m[a.topic]=m[a.topic]||[0,0]);m[a.topic][1]++;if(a.ok)m[a.topic][0]++});
 return Object.entries(m).filter(x=>x[1][1]>=2).map(x=>[x[0],x[1][0]/x[1][1],x[1][1]]).sort((a,b)=>a[1]-b[1])}
function mission(){const w=weak()[0];return w&&w[1]<.7?{t:'Revise '+w[0],why:`Your last ${w[2]} recorded answers on this topic scored ${Math.round(w[1]*100)}%, so a short revision session comes first.`}:
 {t:'Review Azure identity controls',why:'No weak topics recorded yet, so this follows your AZ-104 and SC-500 exam dates. Answer practice questions to personalise this.'}}
function home(){
 const done=!!S.checkins[tk()],c=S.checkins[tk()]||{},mi=mission(),acc=S.attempts.slice(-30),ok=acc.filter(a=>a.ok).length;
 const next=S.certs.filter(x=>x.date&&ms(x.date)>0).sort((a,b)=>ms(a.date)-ms(b.date))[0];
 return `<h1>${greet()}, ${esc(S.name)}</h1><p class="sub m" id="clk"></p>
 <div class="grid g2"><div class="card"><h2>Personal milestone · <span class="m">${esc(S.target)}</span></h2><div class="big glow m" id="cd"></div><p class="note">A personal milestone, not a guaranteed employment deadline. Edit the date in Settings.</p></div>
 <div class="card"><h2>Next exam</h2>${next?`<div class="big m">${esc(next.id)}</div><p class="m" id="ex"></p><p class="note">${esc(next.date)}</p>`:'<p class="note">No dated exams. Add one under Certs.</p>'}</div></div>
 <div class="card"><h2>Daily mission</h2><b style="font-size:18px">${esc(mi.t)}</b><p class="note">${esc(mi.why)}</p><button class="b" onclick="startQuiz()">Take the 5-question briefing</button></div>
 <div class="grid g2"><div class="card"><h2>Today's checklist</h2>${S.tasks.map((t,i)=>`<div class="t"><input type="checkbox" aria-label="done" ${t.done?'checked':''} onchange="tog(${i})"><span class="f" style="${t.done?'opacity:.5;text-decoration:line-through':''}">${esc(t.text)}</span><span class="tag">${t.rec?'recommended':'mine'}</span><button class="s" aria-label="delete" onclick="delT(${i})">×</button></div>`).join('')||'<p class="note">No tasks yet.</p>'}
 <div class="row" style="margin-top:10px"><input class="f" id="nt" placeholder="Add a task"><button class="b" onclick="addT()">Add</button></div>
 ${S.tasks.some(t=>t.rec)?'':'<button class="s" onclick="recT()">Add recommended tasks</button>'}</div>
 <div class="card"><h2>Check-in ${done?'· recorded today':''}</h2>
 <label>What did you study?</label><input id="ci1" value="${esc(c.studied)}"><label>Minutes</label><input id="ci2" type="number" min="0" value="${esc(c.min)}">
 <label>What was difficult?</label><input id="ci3" value="${esc(c.hard)}"><label>Next action</label><input id="ci4" value="${esc(c.next)}">
 <button class="b" onclick="checkin()">${done?'Update today\'s check-in':'Check in for today'}</button></div></div>
 <div class="grid g4"><div class="card"><h2>Streak</h2><div class="big m">${streak()}</div><p class="note">Consecutive days with a check-in</p></div>
 <div class="card"><h2>Hours (7d)</h2><div class="big m">${hours(7).toFixed(1)}</div><p class="note">From logged sessions</p></div>
 <div class="card"><h2>Answered</h2><div class="big m">${S.attempts.length}</div></div>
 <div class="card"><h2>Recent accuracy</h2><div class="big m">${acc.length?Math.round(ok/acc.length*100)+'%':'–'}</div><p class="note">${acc.length?'Last '+acc.length+' answers':'No data yet'}</p></div></div>
 <div class="card"><h2>Your why</h2>${[['a','Aspire'],['e','Escape'],['c','Commit']].map(x=>`<label>${x[1]}</label><textarea rows="2" onchange="S.why.${x[0]}=this.value;save()">${esc(S.why[x[0]])}</textarea>`).join('')}</div>
 <div class="card"><h2>ARES AI</h2><p class="note">Not configured. A server-side model provider is needed, and no replies are simulated here.</p></div>`}
function tog(i){S.tasks[i].done=!S.tasks[i].done;save();render()}
function delT(i){S.tasks.splice(i,1);save();render()}
function addT(){const v=$('nt').value.trim();if(v){S.tasks.push({text:v,done:false,rec:false});save();render()}}
function recT(){['Complete the five-question briefing','Review today\'s recommended topic','Log study time'].forEach(t=>S.tasks.push({text:t,done:false,rec:true}));save();render()}
function checkin(){const min=Math.max(0,+$('ci2').value||0),k=tk();
 S.checkins[k]={studied:$('ci1').value,min,hard:$('ci3').value,next:$('ci4').value,at:new Date().toISOString()};
 S.study=S.study.filter(s=>s.src!==k);if(min)S.study.push({date:new Date().toISOString(),min,topic:$('ci1').value,src:k});save();render()}
function startQuiz(){view='practice';const last={};S.attempts.forEach(a=>last[a.id]=a.ok);
 const qs=[...Q].sort(()=>Math.random()-.5).sort((a,b)=>(last[a[0]]===undefined?0:last[a[0]]?2:1)-(last[b[0]]===undefined?0:last[b[0]]?2:1)).slice(0,5);
 quiz={qs,i:0,sel:[],shown:false,score:0};render()}
function practice(){
 if(!quiz)return `<h1>Practice</h1><p class="sub">Original practice questions, not official exam material. Sample bank of ${Q.length} questions.</p>
 <div class="card feat"><h2>SC-500 practice</h2><p class="note">${Q.filter(q=>q[1]=='SC-500').length} original questions across identity, storage and networking, secure compute including AI, and posture monitoring. Five per session, unseen and missed first.</p><button class="b" onclick="startQuiz('SC-500')">Start SC-500 practice</button></div>
<div class="card"><h2>Daily briefing</h2><p class="note">Five questions, unseen and previously missed ones first.</p><button class="b" onclick="startQuiz()">Start briefing</button></div>
 <div class="card"><h2>Topic performance</h2>${weak().map(w=>`<div class="row"><span class="f">${esc(w[0])}</span><span class="m">${Math.round(w[1]*100)}% · ${w[2]}</span></div>`).join('')||'<p class="note">Answer at least two questions on a topic to see it here.</p>'}</div>`;
 if(quiz.i>=5)return `<h1>Briefing complete, ${esc(S.name)}</h1><div class="card"><div class="big glow m">${quiz.score}/5</div><p class="note">${quiz.score<4?'Revise the topics you missed, they will come up again first.':'Solid work. Missed topics will resurface sooner.'}</p><button class="b" onclick="quiz=null;go('home')">Back to home</button></div>`;
 const q=quiz.qs[quiz.i],multi=q[5].length>1;
 return `${quiz.daily?'<button class="s" style="float:right" onclick="quiz=null;go(\'home\')">Skip to dashboard</button>':''}<p class="note m">Question ${quiz.i+1} of 5 · ${esc(q[1])} · ${esc(q[2])}</p><div class="bar"><i style="width:${quiz.i*20}%"></i></div>
 <div class="card" style="margin-top:12px"><b>${esc(q[3])}</b>${multi?'<p class="note">Select all that apply.</p>':''}
 ${q[4].map((o,i)=>`<button class="opt ${quiz.shown?(q[5].includes(i)?'ok':quiz.sel.includes(i)?'no':''):quiz.sel.includes(i)?'sel':''}" ${quiz.shown?'disabled':''} onclick="pick(${i})">${esc(o)}</button>`).join('')}
 ${quiz.shown?`<div class="why">${esc(q[6])}</div><button class="b" style="margin-top:10px" onclick="quiz.i++;quiz.sel=[];quiz.shown=false;render()">Next</button>`:`<button class="b" ${quiz.sel.length?'':'disabled'} onclick="submitQ()">Submit</button>`}</div>`}
function pick(i){const q=quiz.qs[quiz.i];if(q[5].length>1)quiz.sel=quiz.sel.includes(i)?quiz.sel.filter(x=>x!=i):[...quiz.sel,i];else quiz.sel=[i];render()}
function submitQ(){const q=quiz.qs[quiz.i],ok=quiz.sel.length==q[5].length&&q[5].every(x=>quiz.sel.includes(x));
 if(ok)quiz.score++;S.attempts.push({id:q[0],track:q[1],topic:q[2],ok,at:new Date().toISOString()});save();quiz.shown=true;render()}
function certs(){return `<h1>Certifications</h1><p class="sub">Earned entries are unverified until you confirm them. Readiness is not estimated until enough practice data exists.</p>
 ${S.certs.map((c,i)=>{const n=S.attempts.filter(a=>a.track==c.id),k=n.filter(a=>a.ok).length;return `<div class="card"><div class="row"><b class="f">${esc(c.id)}</b><span class="tag">${esc(c.status)}</span></div>
 <label>Exam date</label><input type="date" value="${esc(c.date)}" onchange="S.certs[${i}].date=this.value;save();render()">
 ${c.date&&ms(c.date)>0?`<p class="m glow">${Math.ceil(ms(c.date)/864e5)} days to go</p>`:''}
 <p class="note">${n.length>=10?`Accuracy ${Math.round(k/n.length*100)}% over ${n.length} answers (estimate)`:n.length?`${n.length} answers so far. Not enough data yet.`:'Not enough data yet.'}</p></div>`}).join('')}`}
function roadmap(){const M=[['Oct to Dec 2026','Foundations and preparation: AZ-104, SC-500, networking, labs, study habits'],['Jan 2027','Entry-level target: SOC internships, learnerships, junior roles'],['Mid 2027','SOC and cloud development'],['2028','Advanced investigation, threat hunting, detection engineering'],['2029','Cloud security architecture, automation, incident response'],['2030','DevSecOps direction']];
 return `<h1>Roadmap</h1><p class="sub">Editable aspirations, not guaranteed outcomes.</p>${M.map((m,i)=>`<div class="card"><div class="t" style="border:0"><input type="checkbox" aria-label="complete" ${S['rm'+i]?'checked':''} onchange="S['rm${i}']=this.checked;save()"><div><b class="m">${m[0]}</b><div class="note">${m[1]}</div></div></div></div>`).join('')}`}
function settings(){return `<h1>Settings</h1>${mem?'<p class="note">Storage is blocked, so changes last only for this session.</p>':''}
 <div class="card"><label>Preferred name</label><input value="${esc(S.name)}" onchange="S.name=this.value||'Jeff';save()">
 <label>Main countdown target</label><input type="date" value="${esc(S.target)}" onchange="S.target=this.value;save();render()">
 <p class="note">Timezone: ${TZ}. Data is stored in this browser only, with no cross-device sync.</p></div>
 ${window.aresSignOut?'<div class="card"><button class="s" onclick="aresSignOut()">Sign out</button></div>':''}<div class="card"><h2>Backup</h2><button class="b" onclick="exp()">Export JSON</button> <button class="s" onclick="$('imp').click()">Restore JSON</button><input id="imp" type="file" accept=".json" hidden onchange="imp(this)">
 <p class="note">AI chat and email reminders need server-side services and are not configured in this prototype.</p></div>
 <div class="card"><button class="s" onclick="if(confirm('Delete ALL ARES data on this device?')){S=JSON.parse(JSON.stringify(def));save();render()}">Clear all data</button></div>`}
function exp(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(S,null,1)],{type:'application/json'}));a.download='ares-backup.json';a.click()}
function imp(el){const f=el.files[0];if(!f)return;f.text().then(t=>{try{const d=JSON.parse(t);if(d.v!==1||!Array.isArray(d.tasks)||!Array.isArray(d.attempts)||!d.checkins||!Array.isArray(d.certs))throw 0;S=d;save();render()}catch(e){alert('That file is not a valid ARES backup.')}})}
function tick(){const c=$('clk');if(c)c.textContent=new Date().toLocaleString('en-GB',{timeZone:TZ,weekday:'short',day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit'})+' SAST';
 const f=x=>{const t=Math.max(0,x);return Math.floor(t/864e5)+'d '+String(Math.floor(t%864e5/36e5)).padStart(2,'0')+'h '+String(Math.floor(t%36e5/6e4)).padStart(2,'0')+'m'};
 if($('cd'))$('cd').textContent=f(ms(S.target));const next=S.certs.filter(x=>x.date&&ms(x.date)>0).sort((a,b)=>ms(a.date)-ms(b.date))[0];if($('ex')&&next)$('ex').textContent=f(ms(next.date))}
const L=(s=28)=>`<svg width="${s}" height="${s}" viewBox="0 0 64 64" aria-hidden="true" style="filter:drop-shadow(0 0 6px rgba(255,122,26,.45))"><path d="M32 5 59 59H46L32 29 18 59H5Z" fill="url(#lg)"/><path d="M32 34l2.2 6.8L41 43l-6.8 2.2L32 52l-2.2-6.8L23 43l6.8-2.2Z" fill="#FF7A1A"/></svg>`;
function nav(){$('nav').innerHTML='<div class="logo">'+L(26)+'ARES</div>'+tabs.map(t=>`<button class="${view==t[0]?'on':''}" onclick="go('${t[0]}')">${t[1]}</button>`).join('')}
const K=(id,name,cat,status,code,cost,note)=>({id,name,cat,status,code:code||'',date:'',cost:cost||0,rev:'',note:note||'',evid:status=='Completed'?'Reported in portfolio, not independently verified':''});
